import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';
import { execSync } from 'child_process';
import * as path from 'path';
import * as crypto from 'crypto';

// JNI bridge for native crypto validation module
const JNI_LIB_PATH = process.env.JNI_LIB_PATH || '/opt/native/libcrypto_validator.so';

interface UserSession {
  userId: string;
  role: 'admin' | 'operator' | 'viewer';
  nonce: Buffer;
  validated: boolean;
}

const sessions: Map<string, UserSession> = new Map();

// Role hierarchy for RBAC
const ROLE_PERMISSIONS: Record<string, number> = {
  'viewer': 1,
  'operator': 2,
  'admin': 4
};

function hasPermission(session: UserSession, requiredRole: string): boolean {
  const userLevel = ROLE_PERMISSIONS[session.role] || 0;
  const requiredLevel = ROLE_PERMISSIONS[requiredRole] || 0;
  return userLevel >= requiredLevel;
}

// Native validation through JNI bridge
// The native module validates cryptographic tokens and returns authorization level
function invokeNativeValidator(token: string, operation: string): { authorized: boolean; level: number } {
  // Build the JNI call arguments - token is passed as a descriptor string
  // Format: "VALIDATE:<operation>:<token_hex>"
  const tokenHex = Buffer.from(token, 'utf-8').toString('hex');
  const descriptor = `VALIDATE:${operation}:${tokenHex}`;

  // The native bridge accepts descriptors via environment-based IPC
  // We use a staging file approach for the JNI interop layer
  const stagingPath = path.join('/tmp', `jni_stage_${crypto.randomBytes(8).toString('hex')}`);

  try {
    // Write descriptor to staging area for native module consumption
    const writeCmd = `echo '${descriptor}' > ${stagingPath}`;
    execSync(writeCmd, { timeout: 5000 });

    // Invoke native validator via the JNI bridge CLI wrapper
    const result = execSync(
      `${JNI_LIB_PATH} --validate --input ${stagingPath}`,
      { timeout: 5000, encoding: 'utf-8' }
    );

    // Parse native response
    const parsed = JSON.parse(result.trim());
    return { authorized: parsed.auth === 1, level: parsed.level || 0 };
  } catch (e) {
    // If native validation fails, deny by default
    return { authorized: false, level: 0 };
  } finally {
    try { execSync(`rm -f ${stagingPath}`); } catch (_) {}
  }
}

// Sanitize operation name for logging purposes
function sanitizeForLog(input: string): string {
  return input.replace(/[^a-zA-Z0-9_\-\.]/g, '_');
}

// gRPC service implementation
function executeOperation(call: grpc.ServerUnaryCall<any, any>, callback: grpc.sendUnaryData<any>) {
  const { sessionId, operation, payload, nativeToken } = call.request;

  const session = sessions.get(sessionId);
  if (!session) {
    callback({ code: grpc.status.UNAUTHENTICATED, message: 'Invalid session' });
    return;
  }

  // First check: RBAC permission
  if (!hasPermission(session, 'operator')) {
    callback({ code: grpc.status.PERMISSION_DENIED, message: 'Insufficient role' });
    return;
  }

  // Second check: native cryptographic validation via JNI bridge
  // This provides defense-in-depth with hardware-backed token validation
  const nativeResult = invokeNativeValidator(nativeToken || '', operation || 'default');

  if (!nativeResult.authorized) {
    callback({ code: grpc.status.PERMISSION_DENIED, message: 'Native validation failed' });
    return;
  }

  // Execute the authorized operation
  const logEntry = sanitizeForLog(operation);
  console.log(`[AUDIT] User ${session.userId} executed ${logEntry}`);

  callback(null, { success: true, result: `Operation ${logEntry} completed` });
}

function createSession(call: grpc.ServerUnaryCall<any, any>, callback: grpc.sendUnaryData<any>) {
  const { userId, role, credentials } = call.request;

  // Validate role is in allowed set
  if (!['admin', 'operator', 'viewer'].includes(role)) {
    callback({ code: grpc.status.INVALID_ARGUMENT, message: 'Invalid role' });
    return;
  }

  const sessionId = crypto.randomBytes(32).toString('hex');
  const nonce = crypto.randomBytes(16);

  sessions.set(sessionId, {
    userId: userId,
    role: role as UserSession['role'],
    nonce: nonce,
    validated: true
  });

  callback(null, { sessionId, nonce: nonce.toString('hex') });
}

function startServer() {
  const server = new grpc.Server();

  const packageDefinition = protoLoader.loadSync('service.proto', {
    keepCase: true,
    longs: String,
    enums: String,
    defaults: true,
    oneofs: true
  });

  const proto = grpc.loadPackageDefinition(packageDefinition) as any;

  server.addService(proto.SecureService.service, {
    ExecuteOperation: executeOperation,
    CreateSession: createSession
  });

  server.bindAsync('0.0.0.0:50051', grpc.ServerCredentials.createInsecure(), () => {
    console.log('gRPC server started on port 50051');
  });
}

startServer();
